contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // require this test contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // observe before state
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint bal_before = address(c).balance;
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;

        bool reverted;
        // call play forwarding sendAmount
        c.play{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint bal_after = address(c).balance;
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;

        // General rule (single assert):
        // - If caller did not send exactly TICKET_AMOUNT (10) then play must revert and
        //   pot and contract balance must be unchanged and bank unchanged.
        // - If caller sent exactly TICKET_AMOUNT and the call did not revert then bank unchanged
        //   and either (A) no payout happened: pot increased by TICKET_AMOUNT and contract balance increased by TICKET_AMOUNT,
        //   or (B) a payout happened: pot became 0 and the contract balance decreased by at least pot_before (i.e., some or all of previous pot left the contract).
        assert(
            // Case: sendAmount != 10 -> must revert and no observable change
            ((sendAmount != 10) && reverted && pot_after == pot_before && bal_after == bal_before && bank_after == bank_before)
            // Case: sendAmount == 10 and not reverted -> bank unchanged and one of the two outcomes
            || ((sendAmount == 10) && !reverted && bank_after == bank_before && (
                // A: no payout happened
                (pot_after == pot_before + sendAmount && bal_after == bal_before + sendAmount)
                // B: payout happened -> pot becomes 0 and contract balance decreased by at least pot_before
                || (pot_after == 0 && bal_before >= bal_after && (bal_before - bal_after) >= pot_before)
            ))
        );
    }

    // allow receiving refunds/payments
    receive() external payable {}
}

