pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 pot_before;
        try c.pot() returns (uint256 __r) { pot_before = __r; } catch { return; }
        uint bal_before = address(c).balance;
        address bank_before;
        try c.bank() returns (address __r) { bank_before = __r; } catch { return; }
        bool reverted;
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 pot_after;
        try c.pot() returns (uint256 __r) { pot_after = __r; } catch { return; }
        uint bal_after = address(c).balance;
        address bank_after;
        try c.bank() returns (address __r) { bank_after = __r; } catch { return; }
        assertTrue(((sendAmount != 10) && reverted && pot_after == pot_before && bal_after == bal_before && bank_after == bank_before)
            // Case: sendAmount == 10 and not reverted -> bank unchanged and one of the two outcomes
            || ((sendAmount == 10) && !reverted && bank_after == bank_before && (
                // A: no payout happened
                (pot_after == pot_before + sendAmount && bal_after == bal_before + sendAmount)
                // B: payout happened -> pot becomes 0 and contract balance decreased by at least pot_before
                || (pot_after == 0 && bal_before >= bal_after && (bal_before - bal_after) >= pot_before)
            )));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
